// Runs once for all items. The Merge node upstream emits a single empty item, so every
// real value here is pulled by name from node 2 and the five fetch nodes.
//
// v1 source-classification ruling (docs/architecture/v1-source-classification-ruling.md):
// nodes 3-7 now use onError: continueErrorOutput, and each node's error output (index 1)
// feeds the same Merge input its main output (index 0) already used. classify() below asks
// n8n's own router which output an item landed on, instead of guessing from item shape --
// item shape cannot tell a dead Supabase apart from an empty Google Sheet: both emit
// { json: {} }.
//
// Fail-closed departure from the ruling as written, on explicit instruction: whether
// $(node).all(1, 0) behaves as documented has never been measured on this instance (ruling
// section 5, item 1). The ruling says a throw while reading the error branch is not proof of
// failure on its own. Here it is: if that read throws, or hands back something that is not a
// list, the source is marked failed immediately, before the main branch is even read. A
// source wrongly called failed only produces a visible warning; a source wrongly called
// healthy produces a false brief, and that is the fault this whole ruling exists to fix.

function toNum(v) {
  if (v === '' || v === undefined || v === null) return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

function previousWeekLabel(label) {
  const m = /^(\d{4})-W(\d{2})$/.exec(String(label || ''));
  if (!m) return null;
  const dt = DateTime.fromObject({ weekYear: Number(m[1]), weekNumber: Number(m[2]), weekday: 1 });
  if (!dt.isValid) return null;
  return dt.minus({ weeks: 1 }).toFormat("kkkk-'W'WW");
}

// The note text for an item that carries an `error` key: its message, or the error itself
// stringified, or a flat fallback -- always truncated to 300 characters.
function errorNote(item) {
  const j = (item && item.json) || {};
  let msg;
  if (j.error && typeof j.error === 'object' && j.error.message) msg = String(j.error.message);
  else if (typeof j.error !== 'undefined') msg = String(j.error);
  else msg = 'The node reported an error.';
  return msg.slice(0, 300);
}

function classify(nodeName) {
  const diagnostics = {
    mainItemCount: 0,
    blankItemCount: 0,
    errorBranchCount: 0,
    errorBranchThrew: false,
    errorBranchMessage: '',
  };

  // 1. The error output. branchIndex is always passed explicitly: after this ruling, two
  //    outputs of this node feed the same Merge input, so the branch n8n would infer by
  //    default is meaningless here.
  let errorItems;
  try {
    errorItems = $(nodeName).all(1, 0);
  } catch (e) {
    diagnostics.errorBranchThrew = true;
    diagnostics.errorBranchMessage = String((e && e.message) || e).slice(0, 300);
    return {
      state: 'failed', ok: false, rowCount: 0, rows: [], diagnostics,
      note: ('Could not read the error output of "' + nodeName + '": ' + diagnostics.errorBranchMessage +
        '. Treated as failed -- fail-closed, see docs/architecture/v1-source-classification-ruling.md.').slice(0, 300),
    };
  }
  if (!Array.isArray(errorItems)) {
    diagnostics.errorBranchThrew = true;
    diagnostics.errorBranchMessage = 'Error output of "' + nodeName + '" did not return a list.';
    return {
      state: 'failed', ok: false, rowCount: 0, rows: [], diagnostics,
      note: (diagnostics.errorBranchMessage + ' Treated as failed -- fail-closed.').slice(0, 300),
    };
  }
  diagnostics.errorBranchCount = errorItems.length;
  if (errorItems.length >= 1) {
    return { state: 'failed', ok: false, rowCount: 0, rows: [], note: errorNote(errorItems[0]), diagnostics };
  }

  // 2. The main output.
  let mainItems;
  try {
    mainItems = $(nodeName).all(0, 0);
  } catch (e) {
    return {
      state: 'failed', ok: false, rowCount: 0, rows: [], diagnostics,
      note: ('Reference to "' + nodeName + '" failed: ' + String((e && e.message) || e)).slice(0, 300),
    };
  }
  if (!Array.isArray(mainItems)) {
    return {
      state: 'failed', ok: false, rowCount: 0, rows: [], diagnostics,
      note: ('Unexpected output shape from "' + nodeName + '".').slice(0, 300),
    };
  }
  diagnostics.mainItemCount = mainItems.length;

  // 3. Belt and braces. Should never fire once every fetch node uses continueErrorOutput --
  //    if it does, some node type routes its error to the main output anyway.
  const erroredMainItem = mainItems.find(i => i && i.json && typeof i.json.error !== 'undefined');
  if (erroredMainItem) {
    return { state: 'failed', ok: false, rowCount: 0, rows: [], note: errorNote(erroredMainItem), diagnostics };
  }

  // 4. A key-less item is alwaysOutputData padding, never a row.
  const rows = [];
  for (const i of mainItems) {
    const j = i && i.json;
    if (j && Object.keys(j).length > 0) rows.push(j);
    else diagnostics.blankItemCount += 1;
  }

  // 5 / 6.
  if (rows.length === 0) {
    return {
      state: 'empty', ok: true, rowCount: 0, rows: [], diagnostics,
      note: 'Empty week: the source was read successfully and had no rows.',
    };
  }
  return { state: 'ok', ok: true, rowCount: rows.length, rows, note: '', diagnostics };
}

const week = $('Set - Define Reporting Week').first().json;

const hubspot  = classify('HubSpot - Fetch Deals And Pipeline');
const supabase = classify('Supabase - Fetch Product Usage');
const finance  = classify('Google Sheets - Fetch Finance Actuals');
const support  = classify('Google Sheets - Fetch Support Log');
const snapshot = classify('Google Sheets - Fetch Last Week Snapshot');

const sourceLabels = {
  hubspot: 'HubSpot deals and pipeline',
  supabase: 'Supabase product usage',
  finance: 'Finance actuals',
  support: 'Support log',
  snapshot: 'Previous weekly snapshot',
};

const sourceResults = { hubspot, supabase, finance, support, snapshot };
const sources = {};
const sourceDiagnostics = {};
for (const k of Object.keys(sourceResults)) {
  const r = sourceResults[k];
  sources[k] = { state: r.state, ok: r.ok, rowCount: r.rowCount, note: r.note };
  sourceDiagnostics[k] = r.diagnostics;
}

const missingSources = Object.keys(sources).filter(k => sources[k].state === 'failed').map(k => sourceLabels[k]);
const emptySources = Object.keys(sources).filter(k => sources[k].state === 'empty').map(k => sourceLabels[k]);
const dataComplete = missingSources.length === 0;
const dataWarning = dataComplete ? '' :
  'Data warning: ' + missingSources.join(', ') + ' could not be read this week. ' +
  'Figures from ' + (missingSources.length > 1 ? 'these sources are' : 'that source is') + ' missing, not zero.';

let alreadyAppended = false;
if (snapshot.state === 'ok' || snapshot.state === 'empty') {
  alreadyAppended = snapshot.rows.some(r => String(r.week_label || '').trim() === week.weekLabel);
}

const lastWeekLabel = previousWeekLabel(week.weekLabel);
const thisWeekFinanceRows = finance.state === 'ok' ? finance.rows.filter(r => String(r.week_label || '').trim() === week.weekLabel) : [];
const lastWeekFinanceRows = (finance.state === 'ok' && lastWeekLabel) ? finance.rows.filter(r => String(r.week_label || '').trim() === lastWeekLabel) : [];

const metrics = thisWeekFinanceRows.map(row => {
  const key = String(row.metric || '').trim();
  const value = toNum(row.actual);
  const target = toNum(row.target);
  const lastRow = lastWeekFinanceRows.find(r => String(r.metric || '').trim() === key);
  const lastWeekValue = lastRow ? toNum(lastRow.actual) : null;

  const variance = (value !== null && target !== null) ? value - target : null;
  const variancePct = (variance !== null && target) ? (variance / target) * 100 : null;
  const wow = (value !== null && lastWeekValue !== null) ? value - lastWeekValue : null;
  const wowPct = (wow !== null && lastWeekValue) ? (wow / lastWeekValue) * 100 : null;

  return {
    key, label: key, unit: '',
    value, target, variance, variancePct,
    lastWeek: lastWeekValue, wow, wowPct,
    sourceName: 'Finance actuals',
    available: finance.state === 'ok' && value !== null,
  };
});

const dealRows = hubspot.state === 'ok' ? hubspot.rows : [];
const stageTotals = {};
let opened = 0, closedWon = 0, closedLost = 0;
for (const d of dealRows) {
  const stage = String(d.dealstage || 'unknown');
  const amount = toNum(d.amount) || 0;
  stageTotals[stage] = (stageTotals[stage] || 0) + amount;
  const s = stage.toLowerCase();
  if (s.indexOf('closedwon') !== -1 || s.indexOf('closed_won') !== -1) closedWon += 1;
  else if (s.indexOf('closedlost') !== -1 || s.indexOf('closed_lost') !== -1) closedLost += 1;
  else opened += 1;
}
const pipeline = {
  byStage: Object.keys(stageTotals).map(stage => ({ stage, value: stageTotals[stage] })),
  movement: { opened, closedWon, closedLost, net: closedWon - closedLost },
};

const revenueTrend = [];
if (snapshot.state === 'ok') {
  for (const r of snapshot.rows) {
    revenueTrend.push({
      weekLabel: String(r.week_label || ''),
      revenue: null,
      synthetic: String(r.synthetic || '').toUpperCase() === 'TRUE',
    });
  }
}
const revenueMetric = metrics.find(m => /revenue/i.test(m.key));
if (revenueMetric) {
  revenueTrend.push({ weekLabel: week.weekLabel, revenue: revenueMetric.value, synthetic: false });
}

let readyToBuild = true;
let blockReason = '';
if (alreadyAppended) {
  readyToBuild = false;
  blockReason = 'A snapshot row for ' + week.weekLabel + ' already exists. Run blocked to avoid a duplicate.';
} else if (missingSources.length === Object.keys(sources).length) {
  readyToBuild = false;
  blockReason = 'All five sources failed. Nothing to report.';
} else if (metrics.length === 0) {
  readyToBuild = false;
  blockReason = 'No metrics were computed: Finance Actuals had no rows for ' + week.weekLabel + '.';
}

return [{
  json: {
    week: { weekStart: week.weekStart, weekEnd: week.weekEnd, weekLabel: week.weekLabel, runId: week.runId, timezone: week.timezone },
    sources, missingSources, emptySources, dataComplete, dataWarning, alreadyAppended, readyToBuild, blockReason,
    metrics, pipeline, revenueTrend, sourceDiagnostics,
  },
}];

// Builds the whole brief as one HTML string (Route A, architecture v1 section 8):
// Drive converts this HTML to a Google Doc, and its remote QuickChart <img> URLs are
// expected to be fetched during that conversion. That fetch-on-convert behaviour is
// UNVERIFIED (Integrator report, priority item 3) -- see node 13's notes.

const metricsData = $('Code - Normalise And Calculate Metrics').first().json;

function escapeHtml(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function fmt(n) {
  if (n === null || n === undefined || !Number.isFinite(n)) return '—';
  return Number(n).toLocaleString('en-GB', { maximumFractionDigits: 2 });
}

function fmtPct(n) {
  if (n === null || n === undefined || !Number.isFinite(n)) return '—';
  return (n >= 0 ? '+' : '') + Number(n).toFixed(1) + '%';
}

// Narrative: several plausible OpenAI simplified-output shapes are tried, since the
// exact field was not independently confirmed, and the node is built disabled per
// money-facts.md until Leo reviews and turns it on.
let narrative = '';
try {
  const ai = $('OpenAI - Write Executive Narrative').first().json;
  narrative = ai && (ai.content || ai.text || ai.output_text || (ai.message && ai.message.content) || '');
} catch (e) {
  narrative = '';
}
if (!narrative || typeof narrative !== 'string' || !narrative.trim()) {
  narrative = 'Narrative unavailable this week: the automated summary could not be generated or read for this run.';
}

const dataWarningHtml = metricsData.dataWarning
  ? '<p style="background:#fff3cd;border:1px solid #ffe69c;padding:10px;font-weight:bold;">' + escapeHtml(metricsData.dataWarning) + '</p>'
  : '';

const emptySourcesHtml = (metricsData.emptySources && metricsData.emptySources.length)
  ? '<p>' + metricsData.emptySources.map(s => escapeHtml(s + ': no data this week.')).join('<br/>') + '</p>'
  : '';

const metricRows = (metricsData.metrics || []).map(m => {
  const valueCell = m.available ? fmt(m.value) : '<span title="' + escapeHtml(metricsData.dataWarning) + '">—</span>';
  return '<tr>' +
    '<td>' + escapeHtml(m.label) + '</td>' +
    '<td>' + valueCell + '</td>' +
    '<td>' + fmt(m.target) + '</td>' +
    '<td>' + fmtPct(m.variancePct) + '</td>' +
    '<td>' + fmtPct(m.wowPct) + '</td>' +
    '</tr>';
}).join('\n');

const kpiTableHtml = (metricsData.metrics && metricsData.metrics.length)
  ? '<table border="1" cellpadding="6" cellspacing="0"><thead><tr>' +
    '<th>Metric</th><th>Actual</th><th>Target</th><th>Variance vs target</th><th>Week over week</th>' +
    '</tr></thead><tbody>' + metricRows + '</tbody></table>'
  : '<p>No metrics were available this week.</p>';

const byStage = metricsData.pipeline && metricsData.pipeline.byStage ? metricsData.pipeline.byStage : [];
let pipelineChartHtml = '<p>No pipeline data available this week.</p>';
if (byStage.length) {
  const pipelineConfig = {
    type: 'bar',
    data: { labels: byStage.map(s => s.stage), datasets: [{ label: 'Pipeline value', data: byStage.map(s => s.value) }] },
    options: { plugins: { title: { display: true, text: 'Pipeline by stage' } } },
  };
  const pipelineUrl = 'https://quickchart.io/chart?width=600&height=350&c=' + encodeURIComponent(JSON.stringify(pipelineConfig));
  pipelineChartHtml = '<img src="' + pipelineUrl + '" alt="Pipeline by stage" width="600" height="350" />';
}

const trendPoints = (metricsData.revenueTrend || []).filter(p => Number.isFinite(p.revenue));
let revenueChartHtml = '<p>Not enough revenue history yet to draw a trend.</p>';
if (trendPoints.length >= 2) {
  const revenueConfig = {
    type: 'line',
    data: { labels: trendPoints.map(p => p.weekLabel + (p.synthetic ? ' (seeded)' : '')), datasets: [{ label: 'Revenue', data: trendPoints.map(p => p.revenue), fill: false }] },
    options: { plugins: { title: { display: true, text: 'Revenue trend' } } },
  };
  const revenueUrl = 'https://quickchart.io/chart?width=600&height=350&c=' + encodeURIComponent(JSON.stringify(revenueConfig));
  revenueChartHtml = '<img src="' + revenueUrl + '" alt="Revenue trend" width="600" height="350" />';
}

const risks = (metricsData.metrics || [])
  .filter(m => m.available && Number.isFinite(m.variancePct) && Math.abs(m.variancePct) >= 10)
  .map(m => '<li>' + escapeHtml(m.label) + ': ' + fmtPct(m.variancePct) + ' vs target</li>')
  .join('\n');
const risksHtml = risks ? '<ul>' + risks + '</ul>' : '<p>No metric is more than 10% off target this week.</p>';

const docTitle = 'Executive Brief - ' + metricsData.week.weekLabel;

const html =
  '<html><body style="font-family:Arial,sans-serif;">' +
  '<h1>' + escapeHtml(docTitle) + '</h1>' +
  dataWarningHtml +
  emptySourcesHtml +
  '<h2>Executive summary</h2><p>' + escapeHtml(narrative).replace(/\n/g, '<br/>') + '</p>' +
  '<h2>KPI table</h2>' + kpiTableHtml +
  '<h2>Pipeline</h2>' + pipelineChartHtml +
  '<h2>Revenue trend</h2>' + revenueChartHtml +
  '<h2>Risks and observations</h2>' + risksHtml +
  '</body></html>';

let summary = (metricsData.dataWarning ? metricsData.dataWarning + '\n\n' : '') +
  'Executive Brief - ' + metricsData.week.weekLabel + '\n' + narrative;
if (summary.length > 3500) summary = summary.slice(0, 3497) + '...';

return [{
  json: {
    docTitle,
    html,
    telegramSummary: summary,
    weekLabel: metricsData.week.weekLabel,
    dataWarning: metricsData.dataWarning,
    dataComplete: metricsData.dataComplete,
  },
}];
